/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let t;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 1) {
    t = lines[0] - 0;
  }

  if (t && lines.length === t + 1) {
    const cases = lines
      .slice(1)
      .map((line) => line.split(" ").map(Number).slice(1));

    getResult(cases);
    lines.length = 0;
  }
});

function getResult(cases) {
  for (let arr of cases) {
    // 对每组测试线段升序排序
    arr.sort((a, b) => a - b);

    const res = [];
    dfs(arr, 0, [], res);

    const count = new Array(100).fill(0);
    for (let i of arr) {
      count[i]++;
    }

    const ans = [];
    canCombine(res, 0, count, 0, ans);
    console.log(Math.max.apply(null, ans));
  }
}

// 全组合求解，即n个数中选3个
function dfs(arr, index, path, res) {
  if (path.length === 3) {
    if (isRightTriangle(path)) res.push([...path]);
    return;
  }

  for (let i = index; i < arr.length; i++) {
    path.push(arr[i]);
    dfs(arr, i + 1, path, res);
    path.pop();
  }
}

// 判断三条边是否可以组成直角三角形
function isRightTriangle(path) {
  const [x, y, z] = path;
  return x * x + y * y === z * z;
}

// 求解当前直角三角形中不超用线段的最多组合数
function canCombine(ts, index, count, num, ans) {
  if (index >= ts.length) {
    ans.push(num);
    return;
  }

  for (let i = index; i < ts.length; i++) {
    const [a, b, c] = ts[i];

    if (count[a] > 0 && count[b] > 0 && count[c] > 0) {
      count[a]--;
      count[b]--;
      count[c]--;
      num++;
      canCombine(ts, i + 1, count, num, ans);
      num--;
      count[a]++;
      count[b]++;
      count[c]++;
    }
  }

  ans.push(num);
}

