function dfs(arr, used, index) {
  let ans = 0;

  for (let i = index; i < arr.length; i++) {
    if (used[i]) continue;

    for (let j = i + 1; j < arr.length; j++) {
      if (used[j]) continue;

      for (let k = j + 1; k < arr.length; k++) {
        if (used[k]) continue;

        if (arr[i] * arr[i] + arr[j] * arr[j] == arr[k] * arr[k]) {
          used[i] = true;
          used[j] = true;
          used[k] = true;

          ans = Math.max(ans, dfs(arr, used, i + 1) + 1);

          used[i] = false;
          used[j] = false;
          used[k] = false;
        }
      }
    }
  }

  return ans;
}

