def dfs(case, used, index):
    ans = 0

    for i in range(index, len(case)):
        if used[i]:
            continue

        for j in range(i + 1, len(case)):
            if used[j]:
                continue

            for k in range(j + 1, len(case)):
                if used[k]:
                    continue

                if case[i] ** 2 + case[j] ** 2 == case[k] ** 2:
                    used[i] = True
                    used[j] = True
                    used[k] = True

                    ans = max(ans, dfs(case, used, i + 1) + 1)

                    used[i] = False
                    used[j] = False
                    used[k] = False

    return ans


